DROP VIEW "public"."proposals_current";--> statement-breakpoint
ALTER TABLE "proposals" ADD COLUMN "unexecutable_at" bigint;--> statement-breakpoint
CREATE VIEW "public"."proposals_current" AS (select "proposals"."id", "proposals"."space_id", "proposals"."proposed_by", "proposals"."created_at", "proposals"."created_at_block", "proposals"."current_version", "proposals"."executed_at", "proposals"."unexecutable_at", "proposal_versions"."proposal_id", "proposal_versions"."proposal_version", "proposal_versions"."voting_mode", "proposal_versions"."start_time", "proposal_versions"."end_time", "proposal_versions"."quorum", "proposal_versions"."threshold", "proposal_versions"."partial_percentage_support_threshold", "proposal_versions"."universal_percentage_support_threshold", "proposal_versions"."flat_support_threshold", "proposal_versions"."execute_by", "proposal_versions"."name", "proposal_versions"."yes_count", "proposal_versions"."no_count", "proposal_versions"."abstain_count", "proposal_versions"."version_created_at", "proposal_versions"."version_created_at_block" from "proposals" inner join "proposal_versions" on "proposal_versions"."proposal_id" = "proposals"."id" AND "proposal_versions"."proposal_version" = "proposals"."current_version");